class Solution {
    companion object{
        const val MOD=1_000_000_007L
    };
    private fun power(baseValue:Long,exponentValue:Long):Long{
        var base=baseValue;
        var exponent=exponentValue;
        var result=1L;
        while(exponent>0){
            if(exponent and 1L==1L)result=result*base%MOD;
            base=base*base%MOD;
            exponent=exponent shr 1
        };
        return result
    };
    fun minNonZeroProduct(p:Int):Int{
        val maximum=(power(2,p.toLong())-1+MOD)%MOD;
        val exponent=(1L shl (p-1))-1;
        return (maximum*power((maximum-1+MOD)%MOD,exponent)%MOD).toInt()
    }
}

